use crate::imagegen::{GeneratedImageBytes, ImageError};
use crate::media::{MediaError, MediaStore};

/// Metadata for a generated image persisted in the content-addressed media store.
#[derive(Debug, Clone)]
pub struct StoredGeneratedImage {
    pub sha256_hex: String,
    pub relative_path: String,
    pub mime_type: String,
    pub byte_len: i64,
}

/// Writes generated bytes to the media store and derives the documented
/// `images/<first2>/<sha256>.<ext>` relative path for metadata only.
pub async fn store_generated_image(
    media: &MediaStore,
    generated: &GeneratedImageBytes,
) -> Result<StoredGeneratedImage, ImageError> {
    let media_ref = media
        .put(
            &generated.bytes,
            &generated.mime_type,
            &format!("generated.{}", generated.extension),
        )
        .await
        .map_err(map_media_error)?;

    let hash = media_ref.media_hash;
    if hash.len() != 64
        || !hash
            .bytes()
            .all(|b| b.is_ascii_digit() || (b'a'..=b'f').contains(&b))
    {
        return Err(ImageError::UpstreamBody(
            "media store returned an invalid content hash".to_string(),
        ));
    }

    let relative_path = format!("images/{}/{}.{}", &hash[..2], hash, generated.extension);
    Ok(StoredGeneratedImage {
        sha256_hex: hash,
        relative_path,
        mime_type: generated.mime_type.clone(),
        byte_len: media_ref.byte_count as i64,
    })
}

/// Reads generated bytes back from the media store by content hash.
pub async fn read_generated_image(
    media: &MediaStore,
    stored: &StoredGeneratedImage,
) -> Result<Vec<u8>, ImageError> {
    media.get(&stored.sha256_hex).await.map_err(map_media_error)
}

fn map_media_error(error: MediaError) -> ImageError {
    ImageError::UpstreamBody(format!("media store rejected generated image: {error}"))
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::imagegen::format::sniff_image;

    const PNG_1X1_BASE64: &str =
        "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+/p8kAAAAASUVORK5CYII=";

    #[tokio::test]
    async fn stores_and_reads_generated_bytes_through_media_store() {
        let root = std::env::temp_dir().join(format!(
            "ai-upcycler-f-media-{}-{}",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .unwrap()
                .as_nanos()
        ));
        let _ = std::fs::remove_dir_all(&root);
        let media = MediaStore::new(root.clone());
        let bytes =
            base64::Engine::decode(&base64::engine::general_purpose::STANDARD, PNG_1X1_BASE64)
                .unwrap();
        let generated = sniff_image(&bytes).unwrap();

        let stored = store_generated_image(&media, &generated).await.unwrap();

        assert!(stored.relative_path.starts_with("images/"));
        assert!(stored.relative_path.ends_with(".png"));
        assert_eq!(stored.mime_type, "image/png");
        assert_eq!(stored.byte_len, bytes.len() as i64);
        assert_eq!(stored.sha256_hex.len(), 64);
        assert_eq!(read_generated_image(&media, &stored).await.unwrap(), bytes);

        let _ = std::fs::remove_dir_all(&root);
    }
}
